[[nodiscard]] reps2::runtime::Status execute_cfg(
    reps2::runtime::EeState& state,
    std::uint64_t instruction_budget
) noexcept {
    std::uint64_t remaining = instruction_budget;
    state.gpr[0] = {};
    const BlockEntry* const begin = std::begin(kBlocks);
    const BlockEntry* const end = std::end(kBlocks);
    for (;;) {
        // A guest syscall handler installed through SetSyscall returns through a
        // kseg3 sentinel address. Complete its context restore before any fetch
        // or address-error check; the sentinel is never fetched.
        if (ee_syscall_handler_return_pending(state)) {
            const Status handler_status = return_from_ee_syscall_handler(state);
            if (handler_status != Status::ok) {
                return handler_status;
            }
            continue;
        }
        // A SIF RPC reply can queue the client's end function. The kernel runs
        // it in interrupt context; here the dispatcher enters it as guest code
        // before the interrupted caller continues (ADR 0136).
        if (ee_guest_callback_pending(state)) {
            const Status callback_status = enter_ee_guest_callback(state);
            if (callback_status != Status::ok) {
                return callback_status;
            }
            continue;
        }
        // The EE DMAC asserts its own COP0 line (Cause IP3, never the INTC). When
        // interrupts are enabled and a handler is registered, REPS2 (the kernel)
        // acknowledges the channel and enters the AddDmacHandler handler as guest
        // code in interrupt context before the interrupted guest continues
        // (ADR 0153).
        if (ee_dmac_line_asserted(state)) {
            const Status interrupt_status = enter_ee_dmac_interrupt(state);
            if (interrupt_status != Status::ok) {
                return interrupt_status;
            }
            continue;
        }
        // The INTC is the other external line (Cause IP2). It is checked after
        // the DMAC because IP3 has the higher priority; when a pending source is
        // mask-enabled and has a registered AddIntcHandler handler, REPS2 (the
        // kernel) acknowledges I_STAT and enters that handler as guest code in
        // interrupt context (ADR 0172).
        if (ee_intc_line_asserted(state)) {
            const Status interrupt_status = enter_ee_intc_interrupt(state);
            if (interrupt_status != Status::ok) {
                return interrupt_status;
            }
            continue;
        }
        // Cooperative scheduling point (ADR 0173): when the active guest
        // context has parked (no live active id) but a READY thread exists,
        // dispatch it before fetching the next block. This is the only place a
        // suspended context yields to another translated one. A parked boot
        // thread that a SignalSema made runnable while a created thread is
        // running resumes here too.
        if (state.hle.active_thread_id == 0U && state.hle.ready_count != 0U) {
            if (!ee_scheduler_pick_ready(state)) {
                return Status::semaphore_wait_blocked;
            }
            continue;
        }
        if (state.hle.main_ready_pending && state.hle.main_context_live) {
            ee_scheduler_resume_main(state);
            continue;
        }
        // Check the next fetch PC on every dispatch, including post-transfer PCs.
        if ((state.pc & 0x3U) != 0U) {
            return raise_ee_address_error(
                state, AddressErrorCode::InstructionFetch, state.pc, false);
        }
        const BlockEntry* const found = std::lower_bound(
            begin, end, state.pc,
            [](const BlockEntry& entry, std::uint32_t pc) { return entry.pc < pc; });
        if (found == end || found->pc != state.pc) {
            return Status::external_control_flow;
        }
        const Status status = found->function(state, remaining);
        if (status != Status::ok) {
            // A guest syscall handler returns through the kseg3 sentinel: the
            // jr $ra block exits as external control flow with pc set to the
            // sentinel. Complete the context restore and resume at the saved PC
            // instead of surfacing a synthetic external target.
            if (status == Status::external_control_flow
                && ee_syscall_handler_return_pending(state)) {
                const Status handler_status = return_from_ee_syscall_handler(state);
                if (handler_status != Status::ok) {
                    return handler_status;
                }
                continue;
            }
            return status;
        }
    }
}

